#!/usr/bin/env bash
# Applies Glow's customizations to the Android project generated by `npx cap add android`:
# icons, the widget's layout, the wallpaper engine's Java code (android-native/), permissions, signing.
set -euo pipefail

RUN="${GITHUB_RUN_NUMBER:-1}"
VERSION="${APP_VERSION:-1.0}"
APP=android/app
RES=$APP/src/main/res
MAN=$APP/src/main/AndroidManifest.xml

# 1) Icons, splash, the notification icon and the widget (layout, drawables, info)
find "$RES" -name 'splash.png' -delete
cp -R android-res/. "$RES/"

# 2) App name (the label under the icon)
STR=$RES/values/strings.xml
perl -0pi -e 's|<string name="app_name">[^<]*</string>|<string name="app_name">Glow</string>|; s|<string name="title_activity_main">[^<]*</string>|<string name="title_activity_main">Glow</string>|' "$STR"

# 3) The wallpaper engine: MainActivity + plugin, alarm, boot receiver, screen watcher, widget
MAIN=$(find "$APP/src/main/java" -name MainActivity.java | head -1)
DIR=$(dirname "$MAIN")
PKG=$(sed -n 's/^package \(.*\);/\1/p' "$MAIN")
[ "$PKG" = "com.luachsport.glow" ] || { echo "unexpected package $PKG"; exit 1; }
cp android-native/*.java "$DIR/"

COMP='        <receiver android:name=".AlarmReceiver" android:exported="false" />
        <receiver android:name=".BootReceiver" android:exported="true">
            <intent-filter>
                <action android:name="android.intent.action.BOOT_COMPLETED" />
                <action android:name="android.intent.action.QUICKBOOT_POWERON" />
                <action android:name="android.intent.action.MY_PACKAGE_REPLACED" />
                <action android:name="android.intent.action.TIME_SET" />
                <action android:name="android.intent.action.TIMEZONE_CHANGED" />
            </intent-filter>
        </receiver>
        <receiver android:name=".GlowWidget" android:exported="true" android:label="Glow">
            <intent-filter>
                <action android:name="android.appwidget.action.APPWIDGET_UPDATE" />
            </intent-filter>
            <meta-data android:name="android.appwidget.provider" android:resource="@xml/glow_widget_info" />
        </receiver>
        <service android:name=".ScreenService" android:exported="false" android:foregroundServiceType="specialUse">
            <property android:name="android.app.PROPERTY_SPECIAL_USE_FGS_SUBTYPE" android:value="Changes the wallpaper each time the screen turns off, as the user chose" />
        </service>
    </application>'
COMP="$COMP" perl -0pi -e 's|    </application>|$ENV{COMP}|' "$MAN"

PERMS='    <uses-permission android:name="android.permission.ACCESS_NETWORK_STATE" />
    <uses-permission android:name="android.permission.SET_WALLPAPER" />
    <uses-permission android:name="android.permission.SET_WALLPAPER_HINTS" />
    <uses-permission android:name="android.permission.RECEIVE_BOOT_COMPLETED" />
    <uses-permission android:name="android.permission.WAKE_LOCK" />
    <uses-permission android:name="android.permission.FOREGROUND_SERVICE" />
    <uses-permission android:name="android.permission.FOREGROUND_SERVICE_SPECIAL_USE" />
    <uses-permission android:name="android.permission.POST_NOTIFICATIONS" />
    <uses-permission android:name="android.permission.REQUEST_IGNORE_BATTERY_OPTIMIZATIONS" />
    <uses-permission android:name="android.permission.VIBRATE" />'
PERMS="$PERMS" perl -0pi -e 's|</manifest>|$ENV{PERMS}\n</manifest>|' "$MAN"

# 4) Violet splash with the glowing circle on Android 12+
STY=$RES/values/styles.xml
perl -0pi -e 's|(<style name="AppTheme.NoActionBarLaunch" parent="Theme.SplashScreen">)|$1\n        <item name="windowSplashScreenBackground">#7A2FD8</item>\n        <item name="windowSplashScreenAnimatedIcon">\@mipmap/ic_launcher_foreground</item>|' "$STY"

# 5) Target SDK 34 (the app is installed directly, not from Play). Lowest Android: Capacitor's own (6.0).
sed -i -E 's/targetSdkVersion = [0-9]+/targetSdkVersion = 34/' android/variables.gradle

# 6) Version: name is the product version, code is the build number (so every APK installs as an update)
sed -i -E "s/versionCode [0-9]+/versionCode ${RUN}/; s/versionName \"[^\"]*\"/versionName \"${VERSION}\"/" "$APP/build.gradle"

# 7) Release signing with the permanent key (password from GitHub secrets)
cat >> "$APP/build.gradle" <<'GRADLE'

android {
    signingConfigs {
        glow {
            storeFile file("release.jks")
            storePassword System.getenv("GLOW_STORE_PASSWORD")
            keyAlias System.getenv("GLOW_KEY_ALIAS")
            keyPassword System.getenv("GLOW_KEY_PASSWORD")
        }
    }
    buildTypes {
        release {
            signingConfig signingConfigs.glow
            minifyEnabled false
        }
    }
}
GRADLE

echo "--- manifest"; grep -n 'permission\|receiver\|service\|property' "$MAN"
echo "--- strings"; cat "$STR"
echo "--- java ($PKG)"; ls "$DIR"
echo "--- launch style"; grep -n -A3 'NoActionBarLaunch' "$STY"
echo "--- versions"; grep -n -E 'versionCode|versionName' "$APP/build.gradle"; grep -n -E 'targetSdk|minSdk' android/variables.gradle
